mapper.select:
SELECT d.id, d.device_id, d.online, d.temperature, d.humidity, d.collect_time, d.receive_time, c.device_name, c.warehouse, c.device_type, c.location FROM wms_env_data d LEFT JOIN wms_env_device c ON c.device_id = d.device_id
AND d.device_id = #{query.deviceId}
AND d.collect_time >= #{query.beginTime}
AND d.collect_time <= #{query.endTime}
ORDER BY d.collect_time DESC
